import React, { useState, useEffect } from "react";
import "./taskflow.css";

const API_URL = "http://localhost:8000/tasks";

function Taskflow() {
    const [search, setSearch] = useState("");
    const [newTask, setNewTask] = useState("");
    const [selectedId, setSelectedId] = useState(null);
    const [tasks, setTasks] = useState([]);

    // 1. Fetch tasks
    const fetchTasks = async (query = "") => {
        try {
            const url = query ? `${API_URL}?search=${encodeURIComponent(query)}` : API_URL;
            const res = await fetch(url);
            const data = await res.json();
            setTasks(data);
        } catch (error) {
            console.error("Error fetching tasks:", error);
        }
    };

    useEffect(() => {
        fetchTasks(search);
    }, [search]);

    // 2. Add task
    async function addTask() {
        if (newTask.trim() === "") return;

        try {
            const res = await fetch(API_URL, {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ title: newTask.trim() }),
            });

            if (res.ok) {
                const createdTask = await res.json();
                setTasks((prev) => [...prev, createdTask]);
                setNewTask("");
            }
        } catch (error) {
            console.error("Error adding task:", error);
        }
    }

    // 3. Edit task
    async function editTask(id, oldTitle) {
        const title = prompt("Edit task:", oldTitle);
        if (title === null || title.trim() === "") return;

        try {
            const res = await fetch(`${API_URL}/${id}`, {
                method: "PUT",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ title: title.trim() }),
            });

            if (res.ok) {
                const updatedTask = await res.json();
                setTasks((prev) => prev.map((t) => (t.id === id ? updatedTask : t)));
            }
        } catch (error) {
            console.error("Error editing task:", error);
        }
    }

    // 4. Toggle completion
    async function toggleCompleted(id) {
        const currentTask = tasks.find((t) => t.id === id);
        if (!currentTask) return;

        try {
            const res = await fetch(`${API_URL}/${id}`, {
                method: "PUT",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ completed: !currentTask.completed }),
            });

            if (res.ok) {
                const updatedTask = await res.json();
                setTasks((prev) => prev.map((t) => (t.id === id ? updatedTask : t)));
            }
        } catch (error) {
            console.error("Error updating status:", error);
        }
    }

    // 5. Delete task
    async function deleteTask(id) {
        try {
            const res = await fetch(`${API_URL}/${id}`, {
                method: "DELETE",
            });

            if (res.ok) {
                setTasks((prev) => prev.filter((t) => t.id !== id));
                if (selectedId === id) setSelectedId(null);
            }
        } catch (error) {
            console.error("Error deleting task:", error);
        }
    }

    function selectTask(id) {
        setSelectedId(selectedId === id ? null : id);
    }

    const selectedTask = tasks.find((t) => t.id === selectedId);

    return (
        <div>
            <header className="header">
                <h1>TaskFlow</h1>
            </header>

            <div className="card">
                <h2>List View</h2>

                <input
                    className="text-box"
                    type="text"
                    placeholder="Search tasks..."
                    value={search}
                    onChange={(e) => setSearch(e.target.value)}
                />

                <div className="add-row">
                    <input
                        className="text-box"
                        type="text"
                        placeholder="Add a new task..."
                        value={newTask}
                        onChange={(e) => setNewTask(e.target.value)}
                    />
                    <button className="add-btn" onClick={addTask}>Add</button>
                </div>

                {tasks.map((task) => (
                    <div className="task" key={task.id}>
                        <div>
                            <input
                                type="checkbox"
                                checked={selectedId === task.id}
                                onChange={() => selectTask(task.id)}
                            />
                            <span className={task.completed ? "title done" : "title"}>
                                {task.title}
                            </span>
                        </div>
                        <div className="task-buttons">
                            <button onClick={() => editTask(task.id, task.title)}>Edit</button>
                            <button onClick={() => deleteTask(task.id)}>Delete</button>
                        </div>
                    </div>
                ))}
            </div>

            {selectedTask && (
                <div className="card">
                    <h2>Detail View</h2>

                    <p className="label">Title</p>
                    <p className="value">{selectedTask.title}</p>

                    <p className="label">Status</p>
                    <p className="value">{selectedTask.completed ? "Completed" : "Pending"}</p>

                    <p className="label">Created</p>
                    <p className="value">
                        {selectedTask.createdAt
                            ? new Date(selectedTask.createdAt).toLocaleDateString("en-US", {
                                month: "short",
                                day: "numeric",
                                year: "numeric",
                            })
                            : "N/A"}
                    </p>

                    <div className="task-buttons">
                        <button onClick={() => toggleCompleted(selectedTask.id)}>
                            {selectedTask.completed ? "Mark as Pending" : "Mark as Completed"}
                        </button>
                        <button onClick={() => deleteTask(selectedTask.id)}>Delete</button>
                    </div>
                </div>
            )}
        </div>
    );
}

export default Taskflow;
